  if (!size) return null;
  const recipe = validateWarPlanetRecipeV115({
    ...base, version: 115, planetSize: size,
    islandShape: parseInt(data.slice(1, 3), 36),
    continentShape: parseInt(data.slice(3, 5), 36),
    regionShape: parseInt(data.slice(5, 7), 36),
